INSERT INTO `articles` VALUES (1,'Eye Care','العناية بالعيون','We provide comprehensive eye care services...','نقدم خدمات شاملة للعناية بالعيون...','https://images.unsplash.com/photo-1582750433449-648ed127bb54?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80','published',0,11,44,'2025-12-22 07:57:38','2025-12-22 07:57:38'),(2,'Dental Services','خدمات طب الأسنان','Our dental clinic offers a full range of dental services...','عيادتنا لطب الأسنان تقدم مجموعة كاملة من الخدمات...','https://backend-v2.aram-gulf.com/images/articles/لقطة شاشة 2025-09-19 145529_69526631b941f.png','published',0,13,13,'2025-12-22 07:57:38','2025-12-29 11:29:53'),(3,'Cardiology','أمراض القلب','Our cardiology department offers specialized care...','يقدم قسم أمراض القلب لدينا رعاية متخصصة...','https://images.unsplash.com/photo-1551076805-e1869033e561?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80','published',0,4,8,'2025-12-22 07:57:38','2025-12-22 07:57:38'),(4,'Pediatrics','طب الأطفال','We provide expert healthcare services for children...','نقدم خدمات رعاية صحية متخصصة للأطفال...','https://images.unsplash.com/photo-1582750433449-648ed127bb54?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80','published',0,13,47,'2025-12-22 07:57:38','2025-12-22 07:57:38'),(5,'Orthopedics','جراحة العظام','Our orthopedic department provides specialized care...','يقدم قسم جراحة العظام لدينا رعاية متخصصة...','https://backend-v2.aram-gulf.com/images/articles/لقطة شاشة 2025-09-19 145529_6952665dcb589.png','published',0,19,20,'2025-12-22 07:57:38','2025-12-29 11:30:37');
