INSERT INTO `home_pages` VALUES (1,'{\"en\":\"\\\"Aram Al Khaleej Company, a cornerstone of digital marketing in Oman.\\\"\",\"ar\":\"شركة آرام الخليج، ركن من اركان التسويق الرقمي في عمان\"}','{\"en\":\"\\\"Elevate your experience with our exclusive premium cards. Enjoy elite privileges and seamless appointment bookings at a wide range of specialized centers. Unlock exceptional benefits and effortless reservation management today.\\\"\\n\",\"ar\":\"\\\"ارتقِ بنمط حياتك مع بطاقاتنا الحصرية؛ استمتع بمزايا استثنائية واحجز مواعيدك بكل سهولة في أرقى المراكز المتخصصة. تجربة فريدة، فوائد لا محدودة، وإدارة حجز سلسة بين يديك.\\\"\\n\"}','[{\"number\":\"50K+\",\"en\":\"Happy Customers\",\"ar\":\"عملاء سعداء\"},{\"number\":\"1M+\",\"en\":\"Bookings Made\",\"ar\":\"عدد الحجوزات\"},{\"number\":\"500+\",\"en\":\"Partner Venues\",\"ar\":\"أماكن شريكة\"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'video',NULL,NULL,'2025-12-22 07:57:38','2026-01-03 21:04:05'),(2,'{\"en\":\"Discover Our Platform\",\"ar\":\"اكتشف منصتنا\"}','{\"en\":\"Embark on an integrated digital journey through our advanced platform, where we design smart solutions that blend efficiency with innovation to meet your aspirations.\",\"ar\":\"انطلق في رحلة رقمية متكاملة عبر منصتنا المطورة، حيث نصمم لك حلولاً ذكية تجمع بين الكفاءة والابتكار لتلبية تطلعاتك\"}','{\"en\":\"Discover a seamless user interface that provides direct access to our diverse services, featuring sophisticated tools for a unique and interactive experience. We are here to empower you to manage your business and track your needs with ease and security, bringing the expertise of \\\"Aram Al-Khaleej\\\" right to your fingertips.\",\"ar\":\" حيث نصمم لك حلولاً ذكية تجمع بين الكفاءة والابتكار لتلبية تطلعاتك. اكتشف واجهة مستخدم سلسة تمنحك وصولاً مباشراً إلى خدماتنا المتنوعة، مع أدوات متقدمة تضمن لك تجربة فريدة وتفاعلية. نحن هنا لنمكّنك من إدارة أعمالك وتتبع احتياجاتك بكل سهولة وأمان، واضعين بين يديك خلاصة خبراتنا في \\\"آرام الخليج\\\".\"}','[{\"en\":\"Trusted and secure services\",\"ar\":\"خدمات موثوقة وآمنة\",\"icon_name\":\"FaServer\"},{\"en\":\"Professional support team\",\"ar\":\"فريق دعم محترف\",\"icon_name\":\"FaUsers\"},{\"en\":\"High customer satisfaction\",\"ar\":\"رضا العملاء العال\",\"icon_name\":\"FaSynagogue\"}]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'swiper','https://backend-v2.aram-gulf.com/images/homepage/رئيسي ارام_695e0d23641ec.png',NULL,'2025-12-22 07:57:38','2026-01-07 07:37:07');
/*!40000 ALTER TABLE `home_pages` ENABLE KEYS */;
