INSERT INTO `organization_terms_conditions` VALUES (1,'We do not share your personal information with third parties without your consent.','نحن لا نشارك معلوماتك الشخصية مع أطراف ثالثة دون موافقتك.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(2,'All collected data is stored securely.','يتم تخزين جميع البيانات التي تم جمعها بشكل آمن.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(3,'You can request to delete your account at any time.','يمكنك طلب حذف حسابك في أي وقت.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(4,'Cookies are used to improve user experience, not for tracking.','يتم استخدام ملفات تعريف الارتباط لتحسين تجربة المستخدم وليس للتتبع.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(5,'Your email address will only be used for communication related to our services.','سيتم استخدام بريدك الإلكتروني فقط للتواصل المتعلق بخدماتنا.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(6,'We comply with GDPR and other data protection regulations.','نحن نلتزم بـ GDPR واللوائح الأخرى لحماية البيانات.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(7,'Payment information is handled by secure third-party providers.','يتم التعامل مع معلومات الدفع بواسطة مزودي خدمات آمنين.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(8,'Access to personal data is restricted to authorized personnel only.','يقتصر الوصول إلى البيانات الشخصية على الموظفين المصرح لهم فقط.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(9,'We regularly update our security measures.','نقوم بتحديث تدابير الأمان لدينا بانتظام.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(10,'User data is anonymized when used for analytics.','يتم إخفاء هوية بيانات المستخدم عند استخدامها للتحليلات.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(11,'We do not sell your data to advertisers.','لا نبيع بياناتك للمعلنين.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(12,'Users are notified of any data breaches promptly.','يتم إخطار المستخدمين بأي اختراقات للبيانات على الفور.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(13,'We provide tools to manage your privacy settings.','نوفر أدوات لإدارة إعدادات الخصوصية الخاصة بك.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(14,'Your preferences for email subscriptions can be modified anytime.','يمكنك تعديل تفضيلاتك للاشتراكات البريدية في أي وقت.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(15,'Data is only retained as long as necessary for the purposes stated.','يتم الاحتفاظ بالبيانات فقط طالما كانت ضرورية للأغراض المحددة.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(16,'Third-party tools used comply with our privacy standards.','الأدوات التي نستخدمها تلتزم بمعايير الخصوصية لدينا.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(17,'We use encryption to protect sensitive information.','نستخدم التشفير لحماية المعلومات الحساسة.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(18,'Our servers are monitored for security 24/7.','تتم مراقبة خوادمنا على مدار الساعة للأمان.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(19,'Children\'s data is handled in compliance with COPPA.','يتم التعامل مع بيانات الأطفال بما يتوافق مع COPPA.','2025-12-22 07:57:49','2025-12-22 07:57:49'),(20,'We welcome your feedback on privacy practices.','نرحب بتعليقاتك حول ممارسات الخصوصية لدينا.','2025-12-22 07:57:49','2025-12-22 07:57:49');
/*!40000 ALTER TABLE `organization_terms_conditions` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `organizations`
--

DROP TABLE IF EXISTS `organizations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `organizations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `accaptable_message` text COLLATE utf8mb4_unicode_ci,
  `unaccaptable_message` text COLLATE utf8mb4_unicode_ci,
  `location` json DEFAULT NULL,
  `phone_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `confirmation_price` decimal(8,2) DEFAULT NULL,
  `confirmation_status` tinyint(1) DEFAULT NULL,
  `open_at` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `close_at` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `url` longtext COLLATE utf8mb4_unicode_ci,
  `image` text COLLATE utf8mb4_unicode_ci,
  `logo` text COLLATE utf8mb4_unicode_ci,
  `verification_code` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email_verified` tinyint(1) NOT NULL DEFAULT '0',
  `email_verification_token` text COLLATE utf8mb4_unicode_ci,
  `active` tinyint(1) NOT NULL DEFAULT '0',
  `status` enum('published','not_published','under_review') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'not_published',
  `rating` decimal(3,2) NOT NULL DEFAULT '0.00',
  `order` int NOT NULL,
  `number_of_reservations` int NOT NULL DEFAULT '0',
  `is_signed` tinyint(1) NOT NULL DEFAULT '0',
  `booking_status` tinyint(1) NOT NULL DEFAULT '0',
  `account_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'organization',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `organizations_email_unique` (`email`),
  UNIQUE KEY `organizations_title_unique` (`title`),
  UNIQUE KEY `organizations_order_unique` (`order`),
  FULLTEXT KEY `organizations_title_description_email_fulltext` (`title`,`description`,`email`)
) ENGINE=InnoDB AUTO_INCREMENT=424 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

