INSERT INTO `privacy_policies` VALUES (1,'We do not share your personal information with third parties without your consent.','نحن لا نشارك معلوماتك الشخصية مع أطراف ثالثة دون موافقتك.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(2,'All collected data is stored securely.','يتم تخزين جميع البيانات التي تم جمعها بشكل آمن.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(3,'You can request to delete your account at any time.','يمكنك طلب حذف حسابك في أي وقت.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(4,'Cookies are used to improve user experience, not for tracking.','يتم استخدام ملفات تعريف الارتباط لتحسين تجربة المستخدم وليس للتتبع.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(5,'Your email address will only be used for communication related to our services.','سيتم استخدام بريدك الإلكتروني فقط للتواصل المتعلق بخدماتنا.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(6,'We comply with GDPR and other data protection regulations.','نحن نلتزم بـ GDPR واللوائح الأخرى لحماية البيانات.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(7,'Payment information is handled by secure third-party providers.','يتم التعامل مع معلومات الدفع بواسطة مزودي خدمات آمنين.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(8,'Access to personal data is restricted to authorized personnel only.','يقتصر الوصول إلى البيانات الشخصية على الموظفين المصرح لهم فقط.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(9,'We regularly update our security measures.','نقوم بتحديث تدابير الأمان لدينا بانتظام.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(10,'User data is anonymized when used for analytics.','يتم إخفاء هوية بيانات المستخدم عند استخدامها للتحليلات.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(11,'We do not sell your data to advertisers.','لا نبيع بياناتك للمعلنين.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(12,'Users are notified of any data breaches promptly.','يتم إخطار المستخدمين بأي اختراقات للبيانات على الفور.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(13,'We provide tools to manage your privacy settings.','نوفر أدوات لإدارة إعدادات الخصوصية الخاصة بك.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(14,'Your preferences for email subscriptions can be modified anytime.','يمكنك تعديل تفضيلاتك للاشتراكات البريدية في أي وقت.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(15,'Data is only retained as long as necessary for the purposes stated.','يتم الاحتفاظ بالبيانات فقط طالما كانت ضرورية للأغراض المحددة.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(16,'Third-party tools used comply with our privacy standards.','الأدوات التي نستخدمها تلتزم بمعايير الخصوصية لدينا.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(17,'We use encryption to protect sensitive information.','نستخدم التشفير لحماية المعلومات الحساسة.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(18,'Our servers are monitored for security 24/7.','تتم مراقبة خوادمنا على مدار الساعة للأمان.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(19,'Children\'s data is handled in compliance with COPPA.','يتم التعامل مع بيانات الأطفال بما يتوافق مع COPPA.','2025-12-22 07:57:38','2025-12-22 07:57:38'),(20,'We welcome your feedback on privacy practices.','نرحب بتعليقاتك حول ممارسات الخصوصية لدينا.','2025-12-22 07:57:38','2025-12-22 07:57:38');
/*!40000 ALTER TABLE `privacy_policies` ENABLE KEYS */;
UNLOCK TABLES;

