INSERT INTO `question_answers` VALUES (1,'ما هو Laravel؟','Laravel هو إطار عمل PHP مفتوح المصدر يستخدم لتطوير تطبيقات الويب.',1,1,NULL,NULL),(2,'ما هي RESTful APIs؟','RESTful APIs هي واجهات برمجة تطبيقات تعتمد على مبادئ REST، وهي تسمح بالتواصل بين الأنظمة المختلفة باستخدام HTTP.',2,1,NULL,NULL),(3,'ما هو الفرق بين GET و POST في HTTP؟','GET يستخدم لجلب البيانات من السيرفر، بينما POST يستخدم لإرسال البيانات إلى السيرفر.',3,1,NULL,NULL),(4,'كيف يمكنني إعداد بيئة تطوير Laravel؟','يمكن إعداد بيئة Laravel باستخدام Composer لتنصيب الحزم، بالإضافة إلى Homestead أو Valet لتوفير بيئة خادم محلي.',4,1,NULL,NULL),(5,'ما هو مفهوم MVC؟','MVC هو اختصار لـ Model-View-Controller، وهو نمط تصميم يستخدم لفصل منطق الأعمال (Model) عن العرض (View) والتحكم (Controller).',5,1,NULL,NULL),(6,'كيف يمكنني التعامل مع قواعد البيانات في Laravel؟','يمكن التعامل مع قواعد البيانات باستخدام Eloquent ORM الخاص بـ Laravel أو من خلال استعلامات SQL التقليدية باستخدام Query Builder.',1,1,NULL,NULL),(7,'ما هو مفهوم Middleware في Laravel؟','Middleware هو طبقة وسيطة يمكن استخدامها لتنفيذ عمليات قبل أو بعد معالجة الطلب في Laravel.',2,1,NULL,NULL),(8,'كيف يمكنني إرسال بريد إلكتروني باستخدام Laravel؟','يمكنك استخدام مكتبة Mail في Laravel لإرسال بريد إلكتروني باستخدام SMTP أو عبر خدمات مثل Mailgun و SendGrid.',3,1,NULL,NULL),(9,'ما هي الحزم في Laravel؟','الحزم في Laravel هي وحدات قابلة لإعادة الاستخدام تضيف ميزات ووظائف جديدة إلى تطبيق Laravel.',4,1,NULL,NULL),(10,'ما هو Artisan؟','Artisan هو أداة سطر أوامر في Laravel تساعد في تنفيذ المهام الروتينية مثل إنشاء الملفات وتنفيذ الهجرات.',5,1,NULL,NULL),(11,'كيف يمكنني تأمين يطاقات ارام ؟','يمكن تأمين بطاقات ارام',1,1,NULL,'2025-12-28 09:15:50'),(12,'ما هو مفهوم Service Container في Laravel؟','Service Container هو أداة قوية في Laravel تُستخدم لإدارة التبعية بين الكائنات.',2,1,NULL,NULL),(13,'ما هي الهجرات (Migrations) في Laravel؟','الهجرات هي طريقة لإدارة إصدار قاعدة البيانات في Laravel، حيث يمكنك إنشاء وتعديل الجداول بسهولة.',3,1,NULL,NULL),(14,'ما هو Blade في Laravel؟','Blade هو محرك القوالب الخاص بـ Laravel والذي يسمح لك بكتابة قوالب ديناميكية باستخدام تركيبات بسيطة.',4,1,NULL,NULL),(15,'كيف يمكنني تنفيذ مصادقة المستخدمين في Laravel؟','يمكنك تنفيذ مصادقة المستخدمين باستخدام نظام Auth المدمج في Laravel الذي يدعم تسجيل الدخول والتسجيل وإدارة الجلسات.',5,1,NULL,NULL),(16,'ما هو الفرق بين Vue.js و React؟','Vue.js و React كلاهما مكتبتان لبناء واجهات المستخدم، لكن React مكتبة موجهة للمكونات بينما Vue.js إطار أكثر تكاملاً.',1,1,NULL,NULL),(17,'كيف يمكنني تحسين أداء تطبيق Laravel؟','يمكن تحسين الأداء باستخدام التخزين المؤقت (caching)، وضبط قواعد البيانات، وتقليل عدد الاستعلامات.',2,1,NULL,NULL),(18,'ما هو مفهوم Pivot Table في Laravel؟','Pivot Table هو جدول وسيط يستخدم لتمثيل العلاقات المتعددة بين الجداول في قاعدة البيانات.',3,1,NULL,NULL),(19,'كيف يمكنني إدارة المهام المجدولة في Laravel؟','يمكنك استخدام Scheduler في Laravel لإدارة المهام المجدولة عبر أوامر Artisan.',4,1,NULL,NULL),(20,'ما هو الفرق بين include و require في PHP؟','include يتضمن ملفًا خارجيًا في حين أن require يوقف تنفيذ البرنامج إذا كان الملف غير موجود.',5,1,NULL,NULL);
/*!40000 ALTER TABLE `question_answers` ENABLE KEYS */;
UNLOCK TABLES;

