INSERT INTO `service_page_cta_sections` VALUES (2,2,'تجارب عملائنا','Our Clients Experiences','حوّل فكرتك إلى تطبيق واقعي','Turn Your Idea into a Real Application','نحن هنا لتحقيق رؤيتك الرقمية','We are here to realize your digital vision','احصل على استشارة مجانية','Get Free Consultation','اطلب عرض سعر','Request a Quote','2025-12-26 15:00:04','2025-12-26 15:00:04'),(3,3,'قصص نجاح عملائنا','Our Clients Success Stories','ابدأ رحلتك في عالم التجارة الإلكترونية','Start Your E-commerce Journey','انضم إلى آلاف التجار الناجحين','Join thousands of successful merchants','احصل على عرض خاص','Get Special Offer','استشارة مجانية','Free Consultation','2025-12-26 15:00:04','2025-12-26 15:00:04'),(4,4,'نجاحات عملائنا تتحدث','Our Clients Success Speaks','ارتقِ بتسويق عملك إلى مستوى جديد','Elevate Your Business Marketing to a New Level','احصل على خطة تسويقية مخصصة لعملك','Get a customized marketing plan for your business','اطلب خطة تسويقية','Request Marketing Plan','استشارة مجانية','Free Consultation','2025-12-26 15:00:04','2025-12-26 15:00:04'),(7,7,'إبداعنا يتحدث','Our Creativity Speaks','اجعل علامتك التجارية لا تُنسى','Make Your Brand Unforgettable','تصميمات إبداعية تحقق أهدافك التسويقية','Creative designs that achieve your marketing goals','اطلب تصميمك الآن','Order Your Design Now','استشارة مجانية','Free Consultation','2025-12-26 15:00:05','2025-12-26 15:00:05'),(8,8,'قصص نجاح عملائنا','Our Clients Success Stories','حول فكرتك إلى فيديو مذهل','Turn Your Idea into an Amazing Video','فريقنا المتخصص جاهز لتحقيق رؤيتك الإبداعية','Our specialized team is ready to realize your creative vision','اطلب فيديو الآن','Order Video Now','استشارة مجانية','Free Consultation','2025-12-26 15:00:05','2025-12-26 15:00:05'),(10,9,'ماذا يقول عملاؤنا','What Our Clients Say','ابدأ رحلتك الرقمية اليوم','Start Your Digital Journey Today','انضم إلى آلاف العملاء الذين وثقوا بنا','Join thousands of customers who trusted us','اطلب الآن','Order Now','تواصل معنا','Contact Us','2025-12-26 15:51:17','2025-12-26 15:51:17'),(12,13,NULL,NULL,'سجل مركزك الآن','\"Register your center now\"','وغير قواعد اللعبة مقارنة بمنافسيك','\"And change the game compared to your competitors.\"\n','','','','','2026-01-07 08:57:44','2026-01-07 08:57:44');
