INSERT INTO `service_page_hero_sections` VALUES (2,2,'الحل الأمثل لإدارة صفحات السوشيال ميديا','\"Your ideal solution for social media management.\"','إدارة سوشيال ميديا احترافية','\"Pro Social Media Management\"','تغيير تجربة العملاء','Transforming Customer Experience','إدارة مبنية على المعرفة بالخوارزميات وقواعد المعرفة والسياسات لوسائل التواصل الاجتماعي','\"Expert management powered by algorithm insights, comprehensive knowledge bases, and platform policies.\"\n',NULL,NULL,NULL,NULL,'https://backend-v2.aram-gulf.com/images/service-pages/اعلانات ارام_695e2beab80f8.png',NULL,'2025-12-26 15:00:04','2026-01-07 09:48:26'),(3,3,'الحملات الإعلانية المدفوعة','social-media-campaigns','حملاتك الإعلانية ','Your Online Campaigns ','بين يديك','At Your Fingertips','ندرس، نحلل، نضع الخطة، ننفذ، ثم نراجع ونحسن من أجل الحصول على نتائج حقيقية ومرضية لعملائنا','\"We study, analyze, plan, execute, then review and improve to achieve real and satisfying results for our clients.\"\n',NULL,NULL,NULL,NULL,'https://backend-v2.aram-gulf.com/images/service-pages/GOLDEN HOUR (2)_69522866cb1f8.png',NULL,'2025-12-26 15:00:04','2025-12-29 07:06:14'),(4,4,'عميلك لا ينتظر','Your Customer doesn\'t waiting ','الرد يجب أن يكون فوري ','\"The response must be immediate.\"','حول كل اتصال إلى عملية بيع','\"Turn every connection into a sale.\"','بوت آرام يعتمد على برمجة عالية الدقة وبسرعة فائقة للرد على عملائك باللغة واللهجة المناسبة وفي الوقت المناسب','\"Aram Bot relies on high-precision programming and lightning-fast speed to respond to your customers in the appropriate language and dialect, at the right time',NULL,NULL,NULL,NULL,'https://backend-v2.aram-gulf.com/images/service-pages/GOLDEN HOUR (5)_69522c484ccae.png',NULL,'2025-12-26 15:00:04','2025-12-29 07:22:48'),(7,7,'التميز في التصميم البصري','Excellence in Visual Design','تصميم جرافيك','Graphic Design','إبداع بلا حدود','Unlimited Creativity','نحول أفكارك إلى تصميمات إبداعية تجذب الأنظار وتنقل رسالتك بفعالية','We turn your ideas into creative designs that attract attention and convey your message effectively',NULL,NULL,NULL,NULL,'/services/service-man.png',NULL,'2025-12-26 15:00:05','2025-12-26 15:00:05'),(8,8,'صناعة المحتوى المرئي الاحترافي','Professional Video Content Production','إنتاج وتحرير الفيديو','Video Production & Editing','قصتك بجودة عالية','Your Story in High Quality','ننتج محتوى فيديو احترافي يحكي قصتك ويوصل رسالتك بأعلى جودة فنية وإبداعية','We produce professional video content that tells your story and delivers your message with the highest technical and creative quality',NULL,NULL,NULL,NULL,'/services/service-man.png',NULL,'2025-12-26 15:00:05','2025-12-26 15:00:05'),(10,9,'كما وعدناكم حلول آرام الذكية في خدمتكم','\"Keeping our promise, Aram Smart Solutions is here to serve you.\"','لمسة واحدة..','One Touch..','عالم من الفرص','A World of Opportunities','استمتع باستخدامات بطاقات NFC الذكية المتعددة وشارك معلوماتك بلمسة واحدة','\"Experience the power of multi-use NFC smart cards—share your info instantly with a single touch.\"',NULL,NULL,NULL,NULL,'https://backend-v2.aram-gulf.com/images/service-pages/GOLDEN HOUR (3)_6951ccf67bcda.png',NULL,'2025-12-26 15:51:17','2025-12-29 00:38:48'),(14,13,'ترويج خدماتك ومنتجاتك يحتاج إلى منصة استثنائية في العالم الرقمي ','\"Promoting your services and products requires an exceptional platform in the digital world.\"','منصة واحدة','One Platform','عملاء أكثر','More customers ','مبيعات أكثر وأرباح أكثر','More Sales & More Profits',NULL,NULL,NULL,NULL,'https://backend-v2.aram-gulf.com/images/service-pages/service-man_695e5682a2c1c.png','','2026-01-07 08:57:44','2026-01-07 12:50:10');
