INSERT INTO `service_page_problem_items` VALUES (164,4,'star','تكاليف عالية','High Costs','الإعلانات التقليدية مكلفة ولا تضمن وصولاً دقيقاً','Traditional ads are expensive and don\'t guarantee accurate reach',0,'2025-12-29 07:22:48','2025-12-29 07:22:48'),(165,4,'book','صعوبة القياس','Difficulty in Measurement','عدم القدرة على تتبع النتائج بدقة','Inability to accurately track results',1,'2025-12-29 07:22:48','2025-12-29 07:22:48'),(166,4,'dollar','ضعف التفاعل','Weak Engagement','الجمهور لا يتفاعل مع الحملات التقليدية','Audience doesn\'t engage with traditional campaigns',2,'2025-12-29 07:22:48','2025-12-29 07:22:48'),(167,7,'FaPalette','تصميمات تقليدية','Traditional Designs','تصميمات مكررة لا تعبر عن هوية فريدة','Repeated designs that don\'t express a unique identity',0,'2025-12-29 10:36:04','2025-12-29 10:36:04'),(168,7,'FaClock','وقت طويل للتنفيذ','Long Execution Time','فترات انتظار طويلة للحصول على التصميم النهائي','Long waiting periods to get the final design',1,'2025-12-29 10:36:04','2025-12-29 10:36:04'),(169,7,'FaMoneyBillAlt','تكاليف غير متوقعة','Unexpected Costs','تكاليف إضافية للتعديلات والتغييرات','Additional costs for modifications and changes',2,'2025-12-29 10:36:04','2025-12-29 10:36:04'),(170,8,'FaVideoSlash','جودة ضعيفة','Poor Quality','مقاطع فيديو بجودة منخفضة لا تجذب المشاهدين','Low quality videos that don\'t attract viewers',0,'2025-12-29 10:50:44','2025-12-29 10:50:44'),(171,8,'FaUserClock','وقت إنتاج طويل','Long Production Time','فترات انتظار طويلة للحصول على المنتج النهائي','Long waiting periods to get the final product',1,'2025-12-29 10:50:44','2025-12-29 10:50:44'),(172,8,'FaDollarSign','تكاليف باهظة','High Costs','أسعار مرتفعة مقابل جودة غير مضمونة','High prices for uncertain quality',2,'2025-12-29 10:50:44','2025-12-29 10:50:44'),(173,8,'FaCreativeCommons','ضعف الإبداع','Lack of Creativity','محتوى مكرر لا يحمل أي عناصر إبداعية مميزة','Repetitive content with no distinctive creative elements',3,'2025-12-29 10:50:44','2025-12-29 10:50:44'),(174,3,'star','منصات معقدة','Complex Platforms','صعوبة في إدارة المتجر والمنتجات','Difficulty in managing store and products',0,'2025-12-29 12:55:24','2025-12-29 12:55:24'),(175,3,'book','تكاليف خفية','Hidden Costs','رسوم إضافية غير متوقعة تزيد التكلفة','Unexpected additional fees increase costs',1,'2025-12-29 12:55:24','2025-12-29 12:55:24'),(176,3,'dollar','ضعف المبيعات','Poor Sales','تصميم غير محفز للشراء وغياب الاستراتيجيات التسويقية','Non-stimulating design for purchases and absence of marketing strategies',2,'2025-12-29 12:55:24','2025-12-29 12:55:24'),(180,10,'star','صعوبة التحديث','Difficult to Update','عند تغيير أي معلومة، عليك طباعة بطاقات جديدة','When any information changes, you have to print new cards',0,'2026-01-01 17:27:52','2026-01-01 17:27:52'),(181,10,'book','غير صديقة للبيئة','Not Eco-Friendly','ملايين البطاقات الورقية تُلقى سنوياً','Millions of paper cards are thrown away annually',1,'2026-01-01 17:27:52','2026-01-01 17:27:52'),(182,10,'dollar','تكلفة متكررة','Recurring Cost','تكاليف الطباعة المتكررة تتراكم مع الوقت','Recurring printing costs accumulate over time',2,'2026-01-01 17:27:52','2026-01-01 17:27:52'),(235,2,'star','بطء الأداء','Poor Performance','تطبيقات بطيئة تؤثر على تجربة المستخدم','Slow applications that affect user experience',0,'2026-01-07 09:48:26','2026-01-07 09:48:26'),(236,2,'book','تصميم غير جذاب','Unattractive Design','واجهات مستخدم قديمة لا تجذب العملاء','Outdated user interfaces that don\'t attract customers',1,'2026-01-07 09:48:26','2026-01-07 09:48:26'),(237,2,'dollar','تكاليف صيانة عالية','High Maintenance Costs','تكاليف صيانة وتحديث مستمرة','Continuous maintenance and update costs',2,'2026-01-07 09:48:26','2026-01-07 09:48:26'),(254,13,'star','أسعار ناااار','Extravagant prices','الترويج لخدماتك ومنتجاتك مكلف للغاية ولا تستطيع مواكبة المنافسين','\"Promoting your services and products is becoming too expensive, making it hard to stay ahead of the competition.\"\n',0,'2026-01-07 12:58:51','2026-01-07 12:58:51'),(255,13,'star','نتائج الإعلانات لا ترقى إلى مستوى التوقعات','\"Advertising results are not meeting expectations.\"','صرفت كثيرا على الإعلانات والمردود قليل جدا','\"High ad spend, but minimal ROI.\"\n',1,'2026-01-07 12:58:51','2026-01-07 12:58:51');
