INSERT INTO `service_page_testimonials` VALUES (127,4,'وليد الشمري','Waleed Al-Shammari','حملاتهم التسويقية زادت مبيعات متجري الإلكتروني بنسبة 400% في 3 أشهر','Their marketing campaigns increased my online store sales by 400% in 3 months',5,'avatars/user1.jpg',0,'2025-12-29 07:22:48','2025-12-29 07:22:48'),(128,4,'هناء الرشيد','Hana Al-Rashid','فريق محترف يقدم تقارير مفصلة وتحليلات دقيقة تساعد في اتخاذ القرارات','Professional team that provides detailed reports and accurate analytics that help in decision making',5,'avatars/user2.jpg',1,'2025-12-29 07:22:48','2025-12-29 07:22:48'),(129,4,'سعود الفهد','Saud Al-Fahad','استراتيجيتهم في التسويق بالمحتوى حولت مدونتنا إلى مصدر رئيسي للعملاء','Their content marketing strategy turned our blog into a major source of customers',5,'avatars/user1.jpg',2,'2025-12-29 07:22:48','2025-12-29 07:22:48'),(130,7,'ريم العلي','Reem Al-Ali','الشعار الذي صمموه لشركتي كان سبباً رئيسياً في نجاح علامتنا التجارية','The logo they designed for my company was a major reason for the success of our brand',5,'avatars/user1.jpg',0,'2025-12-29 10:36:04','2025-12-29 10:36:04'),(131,7,'عمر السفياني','Omar Al-Sufyani','فريق إبداعي يفهم احتياجات العميل ويترجمها إلى تصميمات متميزة','A creative team that understands customer needs and translates them into outstanding designs',5,'avatars/user2.jpg',1,'2025-12-29 10:36:04','2025-12-29 10:36:04'),(132,7,'نوف الخالد','Nouf Al-Khaled','التصاميم التي قدموها لمنصات التواصل الاجتماعي زادت من تفاعل متابعينا بنسبة 500%','The designs they provided for social media platforms increased our followers\' engagement by 500%',5,'avatars/user1.jpg',2,'2025-12-29 10:36:04','2025-12-29 10:36:04'),(133,7,'فيصل القحطاني','Faisal Al-Qahtani','المهنية وسرعة الاستجابة والتعديلات المجانية جعلت التعامل معهم تجربة رائعة','Professionalism, quick response and free revisions made dealing with them a great experience',5,'avatars/user2.jpg',3,'2025-12-29 10:36:04','2025-12-29 10:36:04'),(134,8,'سالم المري','Salem Al-Mary','الفيديو الترويجي الذي أنتجوه لشركتنا حصد أكثر من مليون مشاهدة في أسبوع','The promotional video they produced for our company garnered over one million views in a week',5,'avatars/user1.jpg',0,'2025-12-29 10:50:44','2025-12-29 10:50:44'),(135,8,'لمى السديري','Lama Al-Sudairi','فريق إبداعي يتمتع بخبرة تقنية عالية وسرعة في التسليم','A creative team with high technical expertise and fast delivery',5,'avatars/user2.jpg',1,'2025-12-29 10:50:44','2025-12-29 10:50:44'),(136,8,'نايف الحربي','Naif Al-Harbi','الرسوم المتحركة التي صمموها لعلامتنا التجارية كانت مميزة جداً','The motion graphics they designed for our brand were very distinctive',5,'avatars/user1.jpg',2,'2025-12-29 10:50:44','2025-12-29 10:50:44'),(137,8,'أريج القحطاني','Areej Al-Qahtani','نظموا لنا فعالية بث مباشر ناجحة حضرها أكثر من 5000 شخص','They organized a successful live streaming event attended by over 5,000 people',5,'avatars/user2.jpg',3,'2025-12-29 10:50:44','2025-12-29 10:50:44'),(138,3,'محمد العتيبي','Mohammed Al-Otaibi','زادت مبيعات متجري بنسبة 300% بعد إنشاء المتجر الإلكتروني','My store sales increased by 300% after creating the online store',5,'avatars/user1.jpg',0,'2025-12-29 12:55:24','2025-12-29 12:55:24'),(139,3,'فاطمة الزهراني','Fatima Al-Zahrani','منصة سهلة الاستخدام مع دعم فني ممتاز على مدار الساعة','Easy-to-use platform with excellent 24/7 technical support',5,'avatars/user2.jpg',1,'2025-12-29 12:55:24','2025-12-29 12:55:24'),(140,3,'عبدالله القصيبي','Abdullah Al-Qusaibi','الحلول التسويقية المدمجة ساعدتني في الوصول لعملاء جدد','The integrated marketing solutions helped me reach new customers',5,'avatars/user1.jpg',2,'2025-12-29 12:55:24','2025-12-29 12:55:24'),(143,9,'أحمد الخاطري','Ahmed Alkhatri','خدمة ممتازة! البطاقة غيرت طريقة تواصلي مع العملاء بشكل كامل','Excellent service! The card completely changed how I connect with clients',5,'avatars/user1.jpg',0,'2026-01-01 17:27:52','2026-01-01 17:27:52'),(144,9,'سارة العصيمي','Sara Al-Osaimi','تصميم أنيق وسهولة في الاستخدام. أنصح الجميع بتجربتها','Elegant design and easy to use. I recommend everyone to try it',5,'avatars/user2.jpg',1,'2026-01-01 17:27:52','2026-01-01 17:27:52'),(166,2,'خالد السعيد','Khaled Al-Saeed','التطبيق الذي طوروه لشركتنا زاد من مبيعاتنا بنسبة 40%','The app they developed for our company increased our sales by 40%',5,'avatars/user1.jpg',0,'2026-01-07 09:48:26','2026-01-07 09:48:26'),(167,2,'نورة القحطاني','Nora Al-Qahtani','فريق محترف ونتائج تتجاوز التوقعات','Professional team and results that exceed expectations',5,'avatars/user2.jpg',1,'2026-01-07 09:48:26','2026-01-07 09:48:26');
