--
-- Table structure for table `slides`
--

DROP TABLE IF EXISTS `slides`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `slides` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `image` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` json NOT NULL,
  `description` json NOT NULL,
  `circle_1_color` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `circle_2_color` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `slides`
--

LOCK TABLES `slides` WRITE;
/*!40000 ALTER TABLE `slides` DISABLE KEYS */;
INSERT INTO `slides` VALUES (1,'https://backend-v2.aram-gulf.com/images/slides/slide-1.png','\"{\\\"en\\\":\\\"Exclusive Premium Cards by Aram Gulf Ltd.\\\",\\\"ar\\\":\\\"بطاقات متميزة حصرية من آرام الخليج المحدودة\\\"}\"','\"{\\\"en\\\":\\\"Discover our exclusive premium cards offering special privileges and benefits. Enjoy exclusive discounts, priority access to services, and partnerships with leading brands. Each card is designed to provide exceptional value and enhance your daily experience with personalized advantages.\\\",\\\"ar\\\":\\\"اكتشف بطاقاتنا المتميزة الحصرية التي تقدم امتيازات و فوائد خاصة. استمتع بخصومات حصرية، وصول مميز للخدمات، وشراكات مع علامات تجارية رائدة. كل بطاقة مصممة لتقدم قيمة استثنائية وتعزز تجربتك اليومية بمزايا مخصصة.\\\"}\"','#FF5733','#33C1FF','active','2025-12-22 07:57:38','2025-12-22 07:57:38'),(2,'https://backend-v2.aram-gulf.com/images/slides/slide-2.png','\"{\\\"en\\\":\\\"VIP Membership Advantages with Aram Gulf\\\",\\\"ar\\\":\\\"مزايا العضوية الخاصة مع آرام الخليج\\\"}\"','\"{\\\"en\\\":\\\"Experience VIP benefits including personalized concierge services, exclusive event invitations, and luxury travel privileges. Our premium cards offer escalating rewards and dedicated support, transforming your lifestyle with exceptional service and recognition.\\\",\\\"ar\\\":\\\"جرب مزايا VIP التي تشمل خدمات كونسيرج مخصصة، دعوات حصرية للفعاليات، وامتيازات سرفات فاخرة. بطاقاتنا المتميزة تقدم مكافآت متدرجة ودعم مخصص، محولة نمط حياتك بخدمة استثنائية واعتراف مميز.\\\"}\"','#28A745','#FFC107','active','2025-12-22 07:57:38','2025-12-22 07:57:38'),(3,'https://backend-v2.aram-gulf.com/images/slides/slide-3.png','\"{\\\"en\\\":\\\"Smart Reservation System by Aram Gulf Ltd.\\\",\\\"ar\\\":\\\"نظام الحجز الذكي من آرام الخليج المحدودة\\\"}\"','\"{\\\"en\\\":\\\"Book appointments easily across various specialized centers with our intelligent scheduling system. Enjoy real-time availability, flexible rescheduling, and automated reminders for all your reservation needs in different specialties.\\\",\\\"ar\\\":\\\"احجز مواعيدك بسهولة عبر مراكز متخصصة متنوعة مع نظام الجدولة الذكي لدينا. استمتع بمزايا التوافر الفوري، إعادة الجدولة المرنة، وتذكيرات آلية لجميع احتياجات حجزك في مختلف التخصصات.\\\"}\"','#6F42C1','#20C997','active','2025-12-22 07:57:38','2025-12-22 07:57:38'),(4,'https://backend-v2.aram-gulf.com/images/slides/slide-4.png','\"{\\\"en\\\":\\\"Efficient Center Booking Management\\\",\\\"ar\\\":\\\"إدارة حجز المراكز بكفاءة\\\"}\"','\"{\\\"en\\\":\\\"Streamline appointments across multiple centers and specialties with our comprehensive booking platform. Benefit from waitlist management, provider ratings, and analytics to optimize your schedule and reduce conflicts.\\\",\\\"ar\\\":\\\"بسط جدولة المواعيد عبر مراكز وتخصصات متعددة مع منصة الحجز الشاملة لدينا. استفد من إدارة قوائم الانتظار، تقييمات مقدمي الخدمة، والتحليلات لتحسين جدولك والحد من التعارضات.\\\"}\"','#E83E8C','#FD7E14','active','2025-12-22 07:57:38','2025-12-22 07:57:38');
/*!40000 ALTER TABLE `slides` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `social_accounts`
--

DROP TABLE IF EXISTS `social_accounts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `social_accounts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `whatsapp_number` text COLLATE utf8mb4_unicode_ci,
  `official_account` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `official_state` tinyint(1) NOT NULL DEFAULT '0',
  `gmail_account` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gmail_state` tinyint(1) NOT NULL DEFAULT '0',
