INSERT INTO `todos` VALUES (1,1,'Complete Project Documentation','Finish the API documentation for the new module.','high',0,'2026-01-01 16:56:38','2026-01-01 16:56:38'),(2,1,'Review Pull Requests','Check the pending PRs from the frontend team.','high',0,'2026-01-01 16:56:38','2026-01-01 16:56:38'),(3,1,'Update Dependencies','Run composer update and npm update to get latest packages.','medium',0,'2026-01-01 16:56:38','2026-01-01 16:56:38'),(4,1,'Team Meeting','Weekly sync with the development team.','medium',1,'2026-01-01 16:56:38','2026-01-01 16:56:38'),(5,1,'Clean up temporary files','Remove old logs and temp uploads from verify folder.','low',0,'2026-01-01 16:56:38','2026-01-01 16:56:38'),(6,1,'Research new JS framework','Look into the latest features of Vue 3.','low',1,'2026-01-01 16:56:38','2026-01-01 16:56:38');
